PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?name WHERE {
  ?z rdfs:label ?name .
  FILTER (CONTAINS(LCASE(?name), "perimeter_mid"))
}

SELECT ?p ?pc ?ts ?o WHERE {
  ?p a <http://brick.schema.org/Zone_Air_Temperature> .
  ?p brick:hasLocation [ a brick:Zone ; rdfs:label "Perimeter_mid_ZN_4" ] .
  ?p ref:hasTimeseriesId ?ts .
} LIMIT 20

PREFIX brick: <http://brick.schema.org/>
PREFIX ref: <https://brick.schema.org/ontology/v1/ref#>
SELECT ?p ?pc ?ts WHERE {
  ?z a brick:Zone .
  ?z rdfs:label "Perimeter_mid_ZN_4" .
  ?p brick:isPartOf ?z .
  ?p rdf:type ?pc .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

PREFIX brick: <http://brick.schema.org/>
SELECT ?z WHERE {
  ?z a brick:Zone .
  ?z rdfs:label "Perimeter_mid_ZN_4" .
}

PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?ts WHERE {
  ?point ref:hasTimeseriesId ?ts .
  FILTER (STRSTARTS(STR(?point), "http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05"))
}

